package dev.lightgun

import dev.lightgun.aim.Barrel
import dev.lightgun.aim.ScreenRect
import dev.lightgun.fusion.OneEuroVec
import dev.lightgun.fusion.PoseFuser
import dev.lightgun.fusion.Quat
import dev.lightgun.fusion.Vec3
import dev.lightgun.net.PacketCodec
import dev.lightgun.net.Pairing
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/** Cross-checks the Kotlin implementation against shared/test_vectors.json (generated by the host). */
class SharedVectorsTest {
    private val v = JSONObject(File("../../shared/test_vectors.json").readText())
    private val key = v.getString("key").chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    private fun hex(b: ByteArray) = b.joinToString("") { "%02x".format(it) }

    @Test fun aimPacketsMatchHost() {
        val codec = PacketCodec(key)
        val arr = v.getJSONArray("aim_packets")
        for (i in 0 until arr.length()) {
            val c = arr.getJSONObject(i)
            val f = c.getJSONObject("fields")
            val raw = codec.encodeAim(f.getInt("gun_id"), f.getLong("seq").toInt(), f.getLong("phone_time_ns"),
                f.getDouble("x").toFloat(), f.getDouble("y").toFloat(), f.getInt("flags"), f.getInt("buttons"))
            assertEquals(c.getString("hex"), hex(raw))
        }
    }

    @Test fun ctrlPacketRoundTrip() {
        val c = v.getJSONObject("ctrl_packet")
        val codec = PacketCodec(key)
        val raw = c.getString("hex").chunked(2).map { it.toInt(16).toByte() }.toByteArray()
        val msg = codec.decodeCtrl(raw, raw.size)
        assertNotNull(msg)
        assertEquals("hello", msg!!.getString("type"))
        raw[10] = (raw[10] + 1).toByte()
        assertNull(codec.decodeCtrl(raw, raw.size))
    }

    @Test fun intersectionsMatchHost() {
        val scr = ScreenRect.fromJson(v.getJSONObject("screen"))
        val barrel = Barrel.fromJson(v.getJSONObject("barrel"))
        val rays = v.getJSONArray("rays")
        for (i in 0 until rays.length()) {
            val r = rays.getJSONObject(i)
            val q = r.getJSONArray("q").let { Quat(it.getDouble(0), it.getDouble(1), it.getDouble(2), it.getDouble(3)) }
            val p = r.getJSONArray("p").let { Vec3(it.getDouble(0), it.getDouble(1), it.getDouble(2)) }
            val (o, d) = barrel.ray(q, p)
            val hit = scr.intersect(o, d)
            if (r.isNull("hit")) { assertNull(hit); continue }
            val e = r.getJSONObject("hit")
            assertNotNull(hit)
            assertEquals(e.getDouble("x"), hit!!.x, 1e-9)
            assertEquals(e.getDouble("y"), hit.y, 1e-9)
            assertEquals(e.getBoolean("on"), hit.onScreen)
        }
    }

    @Test fun anchorRoundTrip() {
        val scr = ScreenRect.fromJson(v.getJSONObject("screen"))
        val q = Quat.fromAxes(scr.u, scr.v, scr.n)
        val back = ScreenRect.fromAnchor(scr.center, q, scr.widthM, scr.heightM, 0.0, 0.0)
        assertTrue((back.s0 - scr.s0).norm() < 1e-9)
        assertTrue((back.u - scr.u).norm() < 1e-9 && (back.v - scr.v).norm() < 1e-9)
    }

    @Test fun pairingUri() {
        val p = Pairing.parse("lightgun://192.168.1.20:47800?k=000102030405060708090a0b0c0d0e0f&v=1&id=2")!!
        assertEquals("192.168.1.20", p.host)
        assertEquals(47800, p.port)
        assertEquals(2, p.gunId)
        assertEquals(15.toByte(), p.key[15])
        assertNull(Pairing.parse("http://x"))
    }

    @Test fun fuserConvergesToArcoreAndPredicts() {
        val f = PoseFuser(gain = 0.2, predictionMs = 0.0)
        val w = Vec3(0.0, 0.5, 0.0)  // rad/s yaw
        val truth = { tNs: Long -> Quat.fromRotVec(w * (tNs * 1e-9)) }
        val gyroBias = 0.01
        var t = 1_000_000_000L
        val arOffset = Quat.fromRotVec(Vec3(0.3, 0.0, 0.0))  // AR world differs from gyro frame
        for (i in 0 until 2000) {   // 4 s at 500 Hz
            t += 2_000_000L
            f.onGyro(t, 0f, (w.y + gyroBias).toFloat(), 0f)
            if (i % 16 == 0) f.onArFrame(t - 5_000_000L, arOffset * truth(t - 5_000_000L), Vec3.ZERO, true)
        }
        val est = f.current(t, predict = false)
        assertTrue("err ${Quat.angle(est.q, arOffset * truth(t))}", Quat.angle(est.q, arOffset * truth(t)) < 0.01)
        f.onArFrame(t, Quat.IDENTITY, Vec3.ZERO, false)
        assertTrue(f.current(t, false).gyroOnly)
    }

    @Test fun oneEuroSmoothsJitter() {
        val e = OneEuroVec()
        var t = 0L
        var inSq = 0.0; var outSq = 0.0; var n = 0
        val base = Vec3(0.0, 0.0, -1.0)
        val rnd = java.util.Random(1)
        for (i in 0 until 400) {
            t += 5_000_000L
            val noisy = (base + Vec3(rnd.nextGaussian(), rnd.nextGaussian(), 0.0) * 0.001).normalized()
            val out = e.filter(t, noisy)
            if (i > 100) { inSq += (noisy - base).norm().let { it * it }; outSq += (out - base).norm().let { it * it }; n++ }
        }
        val ratio = Math.sqrt(outSq / n) / Math.sqrt(inSq / n)
        assertTrue("rms ratio $ratio", ratio < 0.5)
    }
}
